process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const PHP_WPAI=Buffer.from('','base64').toString();
const PHP_V22=Buffer.from('','base64').toString();
async function putResult(path, obj){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:`s719 ${new Date().toISOString()}`, content:Buffer.from(JSON.stringify(obj,null,2)).toString('base64')};
  if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function main(){
  const out={steps:[]};
  // 0) deaktyvuoti senus TEMP
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active && /^TEMP/i.test(s.name||''))){
    await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${t.id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
    out.steps.push(`deakt senas TEMP #${t.id}`);
  }
  // 1) WPAI fix
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:'TEMP S719 WPAI CF fix', code:PHP_WPAI.replace(/^<\?php\s*/,''), scope:'global', active:true})});
  const s1=await r.json();
  out.steps.push(`WPAI TEMP #${s1.id} st=${r.status}`);
  if(!s1.id){ out.klaida='WPAI TEMP nesukurtas'; await putResult('analize/s719.json',out); return; }
  await new Promise(s=>setTimeout(s,2000));
  let resp=await fetch(`${WP}/?ps_s719wpai=1&k=wa719rt`,{headers:{Authorization:AUTH}});
  let text=await resp.text();
  out.wpai_http=resp.status;
  try{ out.wpai=JSON.parse(text); }catch(e){ out.wpai_raw=text.slice(0,2000); }
  let d=await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${s1.id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  out.steps.push(`deakt WPAI TEMP #${s1.id} st=${d.status}`);
  // 2) Sources v2.2 deploy
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:'Petshop Sources v2.2 (registras + palaikymas + sandelio pildymas)', code:PHP_V22.replace(/^<\?php\s*/,''), scope:'global', active:true})});
  const s2=await r.json();
  out.steps.push(`v2.2 snippet #${s2.id} st=${r.status}`);
  if(!s2.id){ out.klaida='v2.2 nesukurtas — 2404 LIEKA aktyvus'; await putResult('analize/s719.json',out); return; }
  out.v22_id=s2.id;
  // 3) deaktyvuoti v2.1 (#2404)
  d=await fetch(`${WP}/wp-json/code-snippets/v1/snippets/2404`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  out.steps.push(`deakt v2.1 #2404 st=${d.status}`);
  // 4) sveikatos patikra — ar svetaine gyva
  await new Promise(s=>setTimeout(s,2000));
  resp=await fetch(`${WP}/`,{headers:{Authorization:AUTH}});
  out.svetaine_http=resp.status;
  // 5) sandelisdry
  resp=await fetch(`${WP}/?ps_src=sandelisdry&k=ps2026`,{headers:{Authorization:AUTH}});
  text=await resp.text();
  out.dry_http=resp.status;
  try{ out.dry=JSON.parse(text); }catch(e){ out.dry_raw=text.slice(0,2500); }
  await putResult('analize/s719.json', out);
}
main().catch(async e=>{ await putResult('analize/s719.json',{klaida:String(e)}); });
